import re
import nltk
nltk.download('stopwords')
from nltk.corpus import stopwords
from collections import Counter

# Constants
try:
    STOPWORDS = set(stopwords.words('english'))
except Exception:
    STOPWORDS = {
        "a", "about", "above", "after", "again", "against", "all", "am",
        "an", "and", "any", "are", "as", "at", "be", "because", "been",
        "before", "being", "below", "between", "both", "but", "by", "could",
        "did", "do", "does", "doing", "down", "during", "each", "few", "for",
        "from", "further", "had", "has", "have", "having", "he", "her",
        "here", "hers", "herself", "him", "himself", "his", "how", "i",
        "if", "in", "into", "is", "it", "its", "itself", "just", "me",
        "more", "most", "my", "myself", "no", "nor", "not", "now", "of",
        "off", "on", "once", "only", "or", "other", "our", "ours", "ourselves",
        "out", "over", "own", "same", "she", "should", "so", "some", "such",
        "than", "that", "the", "their", "theirs", "them", "themselves",
        "then", "there", "these", "they", "this", "those", "through", "to",
        "too", "under", "until", "up", "very", "was", "we", "were", "what",
        "when", "where", "which", "while", "who", "whom", "why", "will",
        "with", "you", "your", "yours", "yourself", "yourselves"
    }

def task_func(text, n=2):
    """
    Remove stopwords and duplicate tokens from text, then count n-grams.

    Args:
        text (str): Input text.
        n (int): Size of the n-grams. Default is 2.

    Returns:
        dict: A dictionary mapping n-gram tuples to their counts.
    """
    if text is None:
        return {}

    try:
        n = int(n)
    except (TypeError, ValueError):
        return {}

    if n < 1:
        return {}

    if not isinstance(text, str):
        text = str(text)

    tokens = re.findall(r"\b[a-z0-9']+\b", text.lower())
    if not tokens:
        return {}

    filtered_tokens = []
    seen = set()
    for token in tokens:
        if token in STOPWORDS or token in seen:
            continue
        seen.add(token)
        filtered_tokens.append(token)

    if len(filtered_tokens) < n:
        return {}

    ngrams = (tuple(filtered_tokens[i:i + n]) for i in range(len(filtered_tokens) - n + 1))
    return dict(Counter(ngrams))
